output_text:
[
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "Shopping carts are forbidden in single-file aisles between opposing shelves.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingSideShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileAisle": {
          "and": [
            "betweenOpposingSideShelves",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "enter_single_file_only_cartless",
    "text": "A shopper may enter a single-file aisle only after leaving the cart behind.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "side_shelf_interactions_cartless",
    "text": "Items on side shelves in a narrow aisle must not be interacted with while holding a cart.",
    "abstraction": {
      "state_properties": {
        "sideShelfBay": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "narrowSideShelfBay": {
          "and": [
            "sideShelfBay",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "narrowSideShelfBay",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_open_cross_aisle",
    "text": "If a cart is set down, it must be parked in a wide open cross-aisle, not next to shelves or in a constriction.",
    "abstraction": {
      "state_properties": {
        "openCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "openCrossAisle"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_any_parked_cart",
    "text": "After parking a cart, the shopper is obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCart",
      "discharge": "takeCart"
    }
  },
  {
    "id": "retrieve_after_leaving_single_file",
    "text": "After coming back out of a single-file aisle without a cart, the shopper must retrieve the parked cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "exitSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileAisle",
              "MOVE"
            ]
          },
          "post": {
            "not": "singleFileAisle"
          }
        },
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "exitSingleFileWithoutCart",
      "discharge": "takeCart"
    }
  },
  {
    "id": "wide_front_shelf_service_with_cart",
    "text": "At accessible wide shelf fronts, shoppers should keep the cart with them while interacting with the shelf.",
    "abstraction": {
      "state_properties": {
        "wideShelfFront": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfFront",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "parking_implies_using_no_cart_aisle",
    "text": "A shopper should set the cart down in an open aisle only when they are about to enter a no-cart single-file aisle.",
    "abstraction": {
      "state_properties": {
        "openCrossAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "singleFileAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "setDownCartInOpenAisle": {
          "pre": {
            "and": [
              "openCrossAisle",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCartInOpenAisle",
      "discharge": "enterSingleFileWithoutCart"
    }
  }
]
